steps.snippet:
file_name = str(binding.get("file_name", "")).strip()
if not file_name:
    raise ValueError("binding['file_name'] is missing")

stem = file_name.rsplit(".", 1)[0] if "." in file_name else file_name
idx = None
for name in (file_name, stem):
    idx = device.find(description=f"File {name}", clickable=True)
    if idx is not None:
        break

if idx is None:
    raise ValueError(f"Could not find file row for {file_name!r}")

device.long_press(index=idx)

idx = device.find(description="Delete", clickable=True)
if idx is None:
    idx = device.find(text="Delete", clickable=True)
if idx is None:
    raise RuntimeError("Clickable Delete control not found on current screen")
device.click(index=idx)

file_name = binding["file_name"]

candidates = [file_name]
if file_name.endswith(".md"):
    candidates.append(file_name[:-3])
else:
    candidates.append(file_name + ".md")

idx = None
for candidate in candidates:
    idx = device.find(description=f"File {candidate}", clickable=True)
    if idx is not None:
        break

if idx is None:
    raise RuntimeError(f"Could not find Markor file row for note: {file_name}")

device.long_press(index=idx)

file_name = binding.get("file_name")
if not file_name:
    raise RuntimeError("binding['file_name'] is required")

if device.find(description=f"Selected {file_name}") is None:
    target = device.find(description=f"File {file_name}", clickable=True)
    if target is None:
        raise RuntimeError(f"File '{file_name}' not found")
    device.long_press(index=target)
    device.settle(1)

delete = device.find(description="Delete", clickable=True)
if delete is None:
    more = device.find(description="More options", clickable=True)
    if more is None:
        raise RuntimeError("Delete action not available")
    device.click(index=more)
    device.settle(1)
    delete = device.find(text="Delete", clickable=True)
    if delete is None:
        delete = device.find(description="Delete", clickable=True)
    if delete is None:
        raise RuntimeError("Delete action not available")

device.click(index=delete)
device.settle(1)

file_name = binding["file_name"].strip()
for desc in (f"File {file_name}", f"File {file_name}.md"):
    idx = device.find(description=desc, clickable=True)
    if idx is not None:
        device.long_press(index=idx)
        break
else:
    raise RuntimeError(f"Could not find Markor file row for '{file_name}'")
